/// All routing parameters are passed as query parameters (same as the `plan` GET endpoint - see there for their descriptions). The request body carries only the offset lists. 
pub async fn plan_post(configuration: &configuration::Configuration, plan_post_body: models::PlanPostBody) -> Result<models::Plan200Response, Error<PlanPostError>> {
    // add a prefix to parameters to efficiently prevent name collisions
    let p_body_plan_post_body = plan_post_body;

    let uri_str = format!("{}/api/v6/plan", configuration.base_path);
    let mut req_builder = configuration.client.request(reqwest::Method::POST, &uri_str);

    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }
    req_builder = req_builder.json(&p_body_plan_post_body);

    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;

    let status = resp.status();
    let content_type = resp
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("application/octet-stream");
    let content_type = super::ContentType::from(content_type);

    if !status.is_client_error() && !status.is_server_error() {
        let content = resp.text().await?;
        match content_type {
            ContentType::Json => serde_json::from_str(&content).map_err(Error::from),
            ContentType::Text => return Err(Error::from(serde_json::Error::custom("Received `text/plain` content type response that cannot be converted to `models::Plan200Response`"))),
            ContentType::Unsupported(unknown_type) => return Err(Error::from(serde_json::Error::custom(format!("Received `{unknown_type}` content type response that cannot be converted to `models::Plan200Response`")))),
        }
    } else {
        let content = resp.text().await?;
        let entity: Option<PlanPostError> = serde_json::from_str(&content).ok();
        Err(Error::ResponseError(ResponseContent { status, content, entity }))
    }
}

